script:
frappe.ui.form.on('Purchase Invoice', {
  refresh(frm) {
    // Helper: determine source doctype from request name
    function _erDoctype(name) {
      return name && name.startsWith('ERMC-') ? 'Advanced Expense Request' : 'Expense Request';
    }

    // Set filter for Expense Request dropdown
    if (frm.fields_dict.imogi_expense_request) {
      frm.set_query('imogi_expense_request', () => ({
        filters: {
          docstatus: 1,
          status: ['in', ['Approved', 'PI Created']],
        },
      }));
    }

    // Fix: Force show tax fields (tax_category, taxes_and_charges)
    // These fields are hidden by Frappe's guardian_has_value logic
    // but are CRITICAL for PPN/PPh calculation from Expense Request
    setTimeout(() => {
      const taxFields = ['tax_category', 'taxes_and_charges'];
      const taxesSection = frm.fields_dict.taxes_section;

      // Force show tax fields
      taxFields.forEach(fieldname => {
        const field = frm.fields_dict[fieldname];
        if (field && field.wrapper) {
          $(field.wrapper).removeClass('hide-control');
          $(field.wrapper).show();
        }
      });

      // Force show taxes section
      if (taxesSection && taxesSection.wrapper) {
        $(taxesSection.wrapper).removeClass('empty-section');
        $(taxesSection.wrapper).show();
      }
    }, 100);

    // Show warning if PI is created manually (not from ER)
    if (!frm.doc.imogi_expense_request && frm.doc.__islocal) {
      frm.dashboard.set_headline_alert(
        'Sebaiknya buat Purchase Invoice dari menu <b>Expense Request</b> untuk memastikan PPN/PPh ter-calculate dengan benar',
        'orange'
      );
    }

    // Show info if from ER
    if (frm.doc.imogi_expense_request && !frm.doc.__islocal) {
      frm.dashboard.set_headline_alert(
        'Purchase Invoice dibuat dari ' + _erDoctype(frm.doc.imogi_expense_request) + ': ' + frm.doc.imogi_expense_request,
        'blue'
      );
    }

    // Add "Create Payment Entry" button if PI is from ER and submitted
    if (frm.doc.imogi_expense_request && frm.doc.docstatus === 1 && !frm.doc.__islocal) {
      frm.add_custom_button(__('Create Payment Entry'), async () => {
        frappe.confirm(
          __('Create Payment Entry for this Purchase Invoice from') + ' ' + _erDoctype(frm.doc.imogi_expense_request) + ' ' + frm.doc.imogi_expense_request + '?',
          async () => {
            try {
              // Get ER data first
              const er_data = await frappe.db.get_doc(_erDoctype(frm.doc.imogi_expense_request), frm.doc.imogi_expense_request);

              // Create Payment Entry using get_payment_entry
              frappe.call({
                method: 'erpnext.accounts.doctype.payment_entry.payment_entry.get_payment_entry',
                args: {
                  dt: frm.doc.doctype,
                  dn: frm.doc.name
                },
                callback: function(r) {
                  if (r.message) {
                    const pe = frappe.model.sync(r.message);
                    frappe.set_route('Form', pe[0].doctype, pe[0].name);

                    // Set ER link and auto-fill remarks after navigation
                    setTimeout(() => {
                      const pe_frm = cur_frm;
                      if (pe_frm && pe_frm.doc.doctype === 'Payment Entry') {
                        pe_frm.set_value('imogi_expense_request', frm.doc.imogi_expense_request);
                        const remarks = 'Payment for ' + _erDoctype(er_data.name) + ' ' + er_data.name + ' - ' + (er_data.request_type || '');
                        pe_frm.set_value('remarks', remarks);
                      }
                    }, 500);
                  }
                },
                error: function(r) {
                  frappe.msgprint({
                    title: __('Error'),
                    message: r?.message || __('Failed to create Payment Entry'),
                    indicator: 'red',
                  });
                }
              });
            } catch (error) {
              frappe.msgprint({
                title: __('Error'),
                message: error?.message || __('Failed to create Payment Entry'),
                indicator: 'red',
              });
            }
          }
        );
      }, __('Actions'));
    }
  },
});

frappe.ui.form.on('Payment Entry', {
  refresh(frm) {
    // Helper: determine source doctype from request name
    function _erDoctype(name) {
      return name && name.startsWith('ERMC-') ? 'Advanced Expense Request' : 'Expense Request';
    }

    if (frm.fields_dict.imogi_expense_request) {
      frm.set_query('imogi_expense_request', () => ({
        filters: {
          docstatus: 1,
          status: ['in', ['PI Created']],
        },
      }));
    }

    // Validation: If PE is for PI linked to ER, must be created from PI button
    if (frm.doc.__islocal && frm.doc.payment_type === 'Pay') {
      // Check if references include PI with ER link
      const references = frm.doc.references || [];
      references.forEach(ref => {
        if (ref.reference_doctype === 'Purchase Invoice' && ref.reference_name) {
          frappe.db.get_value('Purchase Invoice', ref.reference_name, 'imogi_expense_request')
            .then(r => {
              if (r.message && r.message.imogi_expense_request) {
                frm.dashboard.set_headline_alert(
                  '<b>Perhatian:</b> Purchase Invoice ini terkait dengan Expense Request. Sebaiknya buat Payment Entry dari button "Create Payment Entry" di Purchase Invoice untuk flow yang benar.',
                  'orange'
                );
              }
            });
        }
      });
    }
  },
  imogi_expense_request(frm) {
    if (!frm.doc.imogi_expense_request) {
      return;
    }
    frappe.call({
      method: 'frappe.client.get',
      args: {
        doctype: _erDoctype(frm.doc.imogi_expense_request),
        name: frm.doc.imogi_expense_request,
      },
      callback(r) {
        if (r.message) {
          const er = r.message;
          if (er.total_amount) {
            frm.set_value('paid_amount', er.total_amount);
            frm.set_value('received_amount', er.total_amount);
          }
          if (!frm.doc.remarks || !frm.doc.remarks.includes('Expense Request')) {
            const remarks = 'Payment for ' + (er.doctype || _erDoctype(er.name)) + ' ' + er.name + ' - ' + (er.request_type || '');
            frm.set_value('remarks', remarks);
          }
        }
      },
    });
  },
});

frappe.ui.form.on('GL Account Mapping Item', {
  account_type(frm, cdt, cdn) {
    // Re-apply filter whenever account_type changes
    refresh_field('account', cdn, 'gl_account_mappings');
  },
  account_parent(frm, cdt, cdn) {
    // Clear account if parent changes
    const row = locals[cdt][cdn];
    if (row.account) {
      frappe.model.set_value(cdt, cdn, 'account', '');
    }
    refresh_field('account', cdn, 'gl_account_mappings');
  },
});

frappe.ui.form.on('Finance Control Settings', {
  refresh(frm) {
    // Apply dynamic filter on 'account' field in gl_account_mappings
    frm.set_query('account', 'gl_account_mappings', function(doc, cdt, cdn) {
      const row = locals[cdt][cdn];
      const filters = { is_group: 0 };
      if (row.account_type) {
        filters['account_type'] = row.account_type;
      }
      if (row.account_parent) {
        filters['parent_account'] = row.account_parent;
      }
      if (doc.company) {
        filters['company'] = doc.company;
      } else if (row.company) {
        filters['company'] = row.company;
      }
      return { filters };
    });

    // Apply dynamic filter on 'account_parent' field in gl_account_mappings
    frm.set_query('account_parent', 'gl_account_mappings', function(doc, cdt, cdn) {
      const row = locals[cdt][cdn];
      const filters = { is_group: 1 };
      if (row.account_type) {
        filters['account_type'] = row.account_type;
      }
      if (doc.company) {
        filters['company'] = doc.company;
      } else if (row.company) {
        filters['company'] = row.company;
      }
      return { filters };
    });
  },
});

frappe.ui.form.on('Expense Request', {
    validate(frm) {

        if (!frm.doc.items) return;

        let accounts = frm.doc.items
            .map(row => row.expense_account)
            .filter(a => a);

        frm.set_value(
            "custom_expense_account_display",
            [...new Set(accounts)].join(", ")
        );

    }
});

frappe.listview_settings['Expense Request'] = {

    formatters: {
        custom_expense_account_display(value) {

            if (!value) return "";

            return `<span style="color:#2563eb;font-weight:600">
                ${value}
            </span>`;
        }
    }

};

frappe.listview_settings['Expense Request'] = {
    onload(listview) {

        setTimeout(() => {

            const container = document.querySelector('.result-list');

            if (container) {
                container.style.overflowX = "auto";
                container.style.whiteSpace = "nowrap";
            }

        }, 500);

    }
};

frappe.listview_settings["Expense Request"] = {
    refresh(listview) {

        function change_label() {
            const header = document.querySelector('[data-sort-by="name"]');
            if (header) {
                header.textContent = "Expense Number";
            }
        }

        change_label();

        // jalankan lagi setelah table render ulang
        setTimeout(change_label, 300);
        setTimeout(change_label, 800);
    }
};
